// Independent serial integer Prim + median-Steiner heuristic, no CUDA/source includes.
#include <vector>
#include <fstream>
#include <string>
#include <algorithm>
#include <stdexcept>
#include <iostream>
#include <numeric>
#include <cstdint>
#include <climits>
using I=int32_t;struct P{I x,y;};struct E{I s,d;};
static void need(bool b,const char*s){if(!b)throw std::runtime_error(s);}static I md(P a,P b){return abs(a.x-b.x)+abs(a.y-b.y);}static I median(I a,I b,I c){return std::max(std::min(a,b),std::min(std::max(a,b),c));}
static std::vector<E> prim(const std::vector<P>&p){int n=p.size();std::vector<I>d(n-1,INT_MAX),dst(n-1),src(n-1);std::iota(dst.begin(),dst.end(),1);std::vector<E>e;int root=0;for(int left=n-1;left>0;left--){I best=INT_MAX;int jbest=-1;for(int j=0;j<left;j++){I nd=md(p[root],p[dst[j]]);if(nd<d[j]){d[j]=nd;src[j]=root;}I score=d[j]*512+j;if(score<best){best=score;jbest=j;}}need(jbest>=0,"Prim candidate");root=dst[jbest];e.push_back({src[jbest],root});d[jbest]=d[left-1];dst[jbest]=dst[left-1];src[jbest]=src[left-1];}return e;}
static bool insert(std::vector<P>&p,const std::vector<E>&edges){int top=p.size();std::vector<std::vector<int>>adj(top);for(int i=0;i<top-1;i++){auto e=edges[i];if(md(p[e.s],p[e.d])){adj[e.s].push_back(i);adj[e.d].push_back(i);}}std::vector<I>d(top-1,-1);for(int s=0;s<top;s++){need(adj[s].size()<=8,"source fixed8 adjacency capacity exceeded");for(size_t j=0;j<adj[s].size();j++)for(size_t k=j+1;k<adj[s].size();k++){int e1=adj[s][j],e2=adj[s][k];auto a=p[s],b=p[edges[e1].s==s?edges[e1].d:edges[e1].s],c=p[edges[e2].s==s?edges[e2].d:edges[e2].s];P q{median(a.x,b.x,c.x),median(a.y,b.y,c.y)};I rd=md(q,a);if(rd>0){d[e1]=std::max(d[e1],rd*512+e2);d[e2]=std::max(d[e2],rd*512+e1);}}}
 std::vector<P>added;for(int e1=0;e1<top-2;e1++){if(d[e1]>0){int e2=d[e1]%512;if(e2>e1&&d[e2]%512==e1){auto a=p[edges[e1].s],b=p[edges[e1].d],c=p[edges[e2].s];if((c.x==a.x&&c.y==a.y)||(c.x==b.x&&c.y==b.y))c=p[edges[e2].d];added.push_back({median(a.x,b.x,c.x),median(a.y,b.y,c.y)});}}}p.insert(p.end(),added.begin(),added.end());return !added.empty();}
static int64_t length(const std::vector<P>&p,const std::vector<E>&e){int64_t l=0;for(auto a:e)l+=md(p[a.s],p[a.d]);return l;}
int main(int argc,char**argv){try{need(argc==3,"fixture oracle arguments");std::ifstream f(argv[1],std::ios::binary);I nets,pins;f.read((char*)&nets,4);f.read((char*)&pins,4);need(f.good()&&nets>0&&pins>0,"fixture header");std::vector<I>idx(nets+1),x(pins),y(pins);f.read((char*)idx.data(),idx.size()*4);f.read((char*)x.data(),x.size()*4);f.read((char*)y.data(),y.size()*4);need(f.good()&&f.peek()==EOF,"full fixture");std::vector<I>oi(nets+1),ox(2*pins,-1),oy(2*pins,-1),es(2*pins,0),ed(2*pins,0),wl;int64_t total=0,bound=0;int maxdegree=0,maxpoints=0,iterations=0;
for(int net=0;net<nets;net++){int begin=idx[net],n=idx[net+1]-begin,out=2*begin;need(n>=2&&n<=256,"pin count");if(n>32)wl.push_back(net);std::vector<P>p;for(int j=begin;j<begin+n;j++)p.push_back({x[j],y[j]});auto original=p;auto initial=prim(p);int64_t upper=length(p,initial);std::vector<E>edges;
if(n==2)edges.push_back({0,1});else if(n==3){p.push_back({median(p[0].x,p[1].x,p[2].x),median(p[0].y,p[1].y,p[2].y)});edges={{0,3},{1,3},{2,3}};}else{int count=0;do{need(++count<1000,"heuristic convergence");need(p.size()<=2*size_t(n),"source output capacity");edges=prim(p);iterations++;}while(insert(p,edges));}
need(p.size()<=2*size_t(n),"final capacity");int64_t l=length(p,edges);need(l<=upper,"Steiner heuristic exceeds terminal MST bound");if(n==3){I xmin=std::min({p[0].x,p[1].x,p[2].x}),xmax=std::max({p[0].x,p[1].x,p[2].x}),ymin=std::min({p[0].y,p[1].y,p[2].y}),ymax=std::max({p[0].y,p[1].y,p[2].y});need(l==int64_t(xmax-xmin)+ymax-ymin,"independent3terminal optimum");}
std::vector<int>par(p.size());std::iota(par.begin(),par.end(),0);auto root=[&](int j){while(j!=par[j])j=par[j];return j;};need(edges.size()+1==p.size(),"tree edge count");for(auto e:edges){need(e.s>=0&&e.d>=0&&size_t(e.s)<p.size()&&size_t(e.d)<p.size(),"edge bounds");int a=root(e.s),b=root(e.d);need(a!=b,"cycle");par[a]=b;}for(size_t j=1;j<p.size();j++)need(root(j)==root(0),"allpoints connected");for(int j=0;j<n;j++)need(p[j].x==original[j].x&&p[j].y==original[j].y,"terminal preservation");
oi[net]=out;for(size_t j=0;j<p.size();j++){ox[out+j]=p[j].x;oy[out+j]=p[j].y;}for(size_t j=0;j<edges.size();j++){es[out+j]=edges[j].s;ed[out+j]=edges[j].d;}total+=l;bound+=upper;maxdegree=std::max(maxdegree,n);maxpoints=std::max(maxpoints,(int)p.size());}
oi[nets]=2*pins;std::ofstream o(argv[2],std::ios::binary);for(auto*v:{&oi,&ox,&oy,&es,&ed})o.write((char*)v->data(),v->size()*4);I w=wl.size();o.write((char*)&w,4);o.write((char*)wl.data(),wl.size()*4);need(o.good(),"oracle output");std::cout<<"{\"nets\":"<<nets<<",\"pins\":"<<pins<<",\"max_input_degree\":"<<maxdegree<<",\"max_solution_points\":"<<maxpoints<<",\"heuristic_iterations\":"<<iterations<<",\"terminal_MST_upper_length\":"<<bound<<",\"Steiner_tree_length\":"<<total<<",\"independent_tree_feasibility\":true,\"global_optimality_claim\":false}\n";
}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}}
